using System;using System.Drawing;using System.Linq;using System.Windows.Forms;using AshkanPharmacy.Core;using AshkanPharmacy.Models;
namespace AshkanPharmacy.Forms{public partial class MedicinesForm:Form{DataGridView g=new DataGridView();TextBox q=new TextBox();public MedicinesForm(){InitializeComponent();BackColor=Color.FromArgb(224,239,246);AutoScroll=true;PageChrome.Header(this,Localization.Persian?"مرکز مدیریت دارو":"Medicine Command Center",Localization.Persian?"کاتالوگ، قیمت، موجودی و انقضا":"Catalog, pricing, stock and expiry intelligence",Color.FromArgb(36,116,166),Color.FromArgb(55,84,148));Build();}Button Btn(string t,int x,Color c){var b=new Button{Text=t,Left=x,Top=205,Width=145,Height=38,BackColor=c,ForeColor=Color.White,FlatStyle=FlatStyle.Flat};b.FlatAppearance.BorderSize=0;return b;}void Build(){var h=new Label{Text=Localization.Persian?"مدیریت داروها و کاتالوگ":"Medicines & Catalog",Left=25,Top=155,Width=500,Height=38,Font=Theme.Font(17,FontStyle.Bold),ForeColor=Theme.Navy};q.SetBounds(25,70,330,36);q.Text=Localization.Persian?"جستجو...":"Search...";var add=Btn(Localization.Persian?"+ افزودن دارو":"+ Add medicine",370,Theme.Teal);var edit=Btn(Localization.Persian?"ویرایش":"Edit",525,Color.FromArgb(27,132,244));var del=Btn(Localization.Persian?"حذف":"Delete",680,Color.FromArgb(226,55,75));g.SetBounds(25,125,1100,500);g.ReadOnly=true;g.AllowUserToAddRows=false;g.SelectionMode=DataGridViewSelectionMode.FullRowSelect;Theme.StyleGrid(g);q.GotFocus+=(s,e)=>{if(q.Text.Contains("..."))q.Clear();};q.TextChanged+=(s,e)=>LoadData();add.Click+=(s,e)=>AddMedicine();edit.Click+=(s,e)=>EditMedicine();del.Click+=(s,e)=>DeleteMedicine();Controls.AddRange(new Control[]{h,q,add,edit,del,g});LoadData();}Medicine Selected(){if(g.CurrentRow==null)return null;int id=Convert.ToInt32(g.CurrentRow.Cells["Id"].Value);return AppStore.Medicines.FirstOrDefault(x=>x.Id==id);}void AddMedicine(){using(var f=new MedicineEditorForm()){if(f.ShowDialog(this)==DialogResult.OK){if(AppStore.PersistentMode){f.Result.Id=MedicineRepository.Insert(f.Result);AuditRepository.Log("Create","Medicine",f.Result.NameEn);}else{f.Result.Id=AppStore.Medicines.Count==0?1:AppStore.Medicines.Max(x=>x.Id)+1;}AppStore.Medicines.Add(f.Result);LoadData();}}}void EditMedicine(){var m=Selected();if(m==null)return;using(var f=new MedicineEditorForm(m)){if(f.ShowDialog(this)==DialogResult.OK){if(AppStore.PersistentMode)MedicineRepository.Update(m);AuditRepository.Log("Update","Medicine",m.NameEn);LoadData();}}}void DeleteMedicine(){var m=Selected();if(m==null)return;if(MessageBox.Show(Localization.Persian?"داروی انتخاب‌شده حذف شود؟":"Delete selected medicine?","Ashkan Pharmacy",MessageBoxButtons.YesNo)==DialogResult.Yes){if(AppStore.PersistentMode)MedicineRepository.Delete(m.Id);AppStore.Medicines.Remove(m);AuditRepository.Log("Delete","Medicine",m.NameEn);LoadData();}}void LoadData(){var s=q.Text??"";var x=AppStore.Medicines.Where(m=>s.Contains("...")||m.NameFa.Contains(s)||m.NameEn.ToLower().Contains(s.ToLower())||m.Barcode.Contains(s)).Select(m=>new{m.Id,Name=Localization.Persian?m.NameFa:m.NameEn,m.Barcode,m.Category,m.Stock,Min=m.MinStock,SellPrice=m.SellPrice,Expiry=m.Expiry,Batch=m.Batch,m.Manufacturer,State=m.Stock<=m.MinStock?(Localization.Persian?"کمبود":"Low"):(Localization.Persian?"مناسب":"OK")}).ToList();g.DataSource=x;}}}
